'use strict';
const DFC=()=>TPDefinitions;
const dfButton=(label,action,id='')=>`<button type="button" class="button small" data-definition="${action}" data-id="${esc(id)}">${label}</button>`;
function dfCatalogWrite(action){if(Team.loaded&&(!Team.permissions?.catalog||teamCurrent()?.readOnly))throw Error('Chỉ người có quyền danh mục được thay đổi bảng dùng chung');mutation(action,{preserveQuote:true});}
function dfParameterChoices(fields){
  const choices=TPConventions.entries(db,'parameters').filter(x=>/^[A-Za-z][A-Za-z0-9_]{0,23}$/.test(x.name)&&!['RHO','PI','BW','SA','CW','CA','PHOI_POLY_L','PHOI_POLY_W','PHOI_POLY_S','PHOI_D','PHOI_R','KL_DV','DT_DV','constructor','prototype','__proto__'].includes(x.name)&&['mm','number','kg/m','m²/m'].includes(x.unit));
  for(const f of fields)if(f.key&&!choices.some(x=>x.name===f.key))choices.push({name:f.key,label:f.name||TPConventions.parameterName(db,f.key),unit:f.unit});
  return choices;
}
function dfRows(fields){const choices=dfParameterChoices(fields);return fields.map((f,i)=>`<tr><td>${select('Ký hiệu','key'+i,[['','Chọn thông số'],...choices.filter(x=>x.name===f.key||!fields.some(v=>v.key===x.name)).map(x=>[x.name,x.name+' — '+(fields.find(f=>f.key===x.name)?.name||x.label||'Chưa khai tên')])],f.key,'required data-df-parameter data-previous="'+esc(f.key)+'"')}</td><td>${field('Tên thông số','fieldName'+i,f.name||TPConventions.parameterName(db,f.key),'text','required maxlength="120"')}</td><td>${select('Nơi nhập','mode'+i,[['fixed','Cố định theo mã'],['input','Nhập tại báo giá'],['output','Kích thước khai triển']],f.mode)}</td><td>${select('Đơn vị','unit'+i,['mm','number','kg/m','m²/m'],f.unit)}</td><td>${field('Số thử','sample'+i,f.sample,'number','min="0" step="any" required')}</td><td>${dfButton('Bỏ thông số','drop-field',String(i))}</td></tr>`).join('');}
function dfOutputRows(d){const outputs=d.unfoldOutputs||[],choices=TPConventions.entries(db,'parameters').filter(x=>x.unit==='mm'&&!d.fields.some(f=>f.key===x.name));return outputs.map((o,i)=>{const options=[...choices];if(o.key&&!options.some(x=>x.name===o.key))options.push({name:o.key,label:o.name});return `<tr data-df-output-row><td>${select('Ký hiệu','outputKey'+i,[['','Chọn thông số'],...options.filter(x=>x.name===o.key||!outputs.some(v=>v.key===x.name)).map(x=>[x.name,x.name+' — '+(x.label||x.name)])],o.key,'required data-df-output-key data-previous="'+esc(o.key)+'"')}</td><td>${field('Tên thông số','outputName'+i,o.name||TPConventions.parameterName(db,o.key),'text','required maxlength="120"')}</td><td>${select('Nơi nhập','outputMode'+i,[['fixed','Cố định theo mã'],['input','Nhập tại báo giá'],['output','Kích thước khai triển']],'output')}</td><td>mm</td><td>${field('Công thức khai triển (mm)','outputFormula'+i,o.formula,'text','required maxlength="500"')}${dfFormulaToolButton('outputFormula'+i)}<output data-df-output-result="${i}">—</output></td><td>${dfButton('Bỏ thông số','drop-output',String(i))}</td></tr>`;}).join('');}

function dfParameterTools(){return `<p class="help-text">Chọn ký hiệu từ Thông số cấu kiện để lấy tên và đơn vị. Khi đổi ký hiệu, các công thức trong bản đang sửa sẽ đổi theo.</p><details id="definition-new-parameter"><summary>Khai thông số mới vào danh mục</summary><div class="form-grid">${field('Ký hiệu mới','dfNewKey','','text','maxlength="24"')}${field('Tên thông số mới','dfNewLabel','','text','maxlength="120"')}${select('Đơn vị thông số mới','dfNewUnit',['mm','number','kg/m','m²/m'],'mm')}${select('Sử dụng thông số mới','dfNewMode',[['input','Đầu vào tại báo giá'],['output','Kích thước khai triển theo công thức']],'input')}</div><button type="button" class="button" id="df-save-parameter">Lưu thông số vào danh mục</button><p id="df-parameter-error" role="status"></p></details>`;}
function dfBindParameters(form,id,read){
  const formulaNames=['length','width','mass','surface','blankMass','blankSurface',...Array.from(form.querySelectorAll('[name^=outputFormula]'),x=>x.name)];
  const helper=form.querySelector('[data-df-for]'),target=helper.querySelector('[data-df-target]');
  const editable=name=>{const input=form.elements.namedItem(name);return input&&!input.disabled&&!input.readOnly&&!(name==='width'&&form.elements.base.value!=='sheet');};
  const activate=name=>{if(!formulaNames.includes(name)||!editable(name))return;helper.dataset.dfFor=name;helper.open=true;refresh();};
  const draft=()=>({...read(new FormData(form)),_testDensity:form.elements.testDensity.value,_testStockL:form.elements.testStockL.value,_testStockW:form.elements.testStockW.value,_testCount:form.elements.testCount.value,_testKerf:form.elements.testKerf.value});
  const refresh=()=>{
    const current=read(new FormData(form)),fields=current.fields,outputs=current.unfoldOutputs||[],choices=dfParameterChoices(fields);
    for(const [i,f]of fields.entries()){
      const el=form.elements['key'+i];
      el.innerHTML=[['','Chọn thông số'],...choices.filter(x=>x.name===f.key||!fields.some(v=>v.key===x.name)).map(x=>[x.name,x.name+' — '+(fields.find(f=>f.key===x.name)?.name||x.label||'Chưa khai tên')])].map(([key,label])=>`<option value="${esc(key)}" ${key===f.key?'selected':''}>${esc(label)}</option>`).join('');
    }
    const symbols=DFC().unfoldSymbols(current);
    const buttons=items=>items.map(([key,label,unit])=>`<button type="button" class="button small" data-df-insert="${esc(key)}" title="${esc(label+(unit?' ('+unit+')':''))}"><b>${esc(key)}</b> · ${esc(label)}${unit?' ('+esc(unit)+')':''}</button>`).join('');
    const labels={length:symbols.length+' · Dài khổ bao',width:symbols.width+' · Rộng khổ bao',mass:'K · Khối lượng vật tư trên đơn vị',surface:'A · Diện tích vật tư trên đơn vị',blankMass:'Khối lượng phôi sản phẩm',blankSurface:'Diện tích phôi sản phẩm'};
    outputs.forEach((o,i)=>labels['outputFormula'+i]=(o.key||'Kích thước khai triển')+' · '+(o.name||'Công thức khai triển'));
    if(!editable(helper.dataset.dfFor))helper.dataset.dfFor=formulaNames.find(editable)||'';
    helper.querySelector('[data-df-active-expression]').textContent=form.elements.namedItem(helper.dataset.dfFor)?.value||'Chưa nhập công thức';
    target.innerHTML=formulaNames.filter(editable).map(name=>`<option value="${name}" ${name===helper.dataset.dfFor?'selected':''}>${esc(labels[name])}</option>`).join('');
    for(const name of formulaNames){const input=form.elements.namedItem(name);input.classList.toggle('df-active-formula',name===helper.dataset.dfFor);}
    const ownOutput=/^outputFormula/.test(helper.dataset.dfFor)?outputs[Number(helper.dataset.dfFor.slice(13))]?.key:null;
    const unfolded=outputs.length?outputs.filter(o=>o.key&&o.key!==ownOutput).map(o=>[o.key,o.name||TPConventions.parameterName(db,o.key),'mm']):[];
    const blank=['blankMass','blankSurface'].includes(helper.dataset.dfFor);
    const derived=[...unfolded,...(current.polygon&&!ownOutput?[['PHOI_POLY_L','Dài bao đa giác','mm'],['PHOI_POLY_W','Rộng bao đa giác','mm'],['PHOI_POLY_S','Diện tích biên đa giác','mm²']]:[]),...(blank?[...(!outputs.length?[[symbols.length,'Dài khai triển','mm'],...(current.base==='sheet'?[[symbols.width,'Rộng khai triển','mm']]:[])]:[]),['KL_DV','Khối lượng trên đơn vị',current.base==='sheet'?'kg/m²':'kg/m'],['DT_DV','Diện tích trên đơn vị',current.base==='sheet'?'m²/m²':'m²/m']]:[])];
    helper.querySelector('[data-df-variables]').innerHTML=`<p>Thông số đầu vào</p><div class="actions">${buttons(fields.filter(f=>f.key).map(f=>[f.key,f.name||TPConventions.parameterName(db,f.key),f.unit]))}</div>${derived.length?'<p>Kết quả đã tính · kích thước khai triển và định mức</p><div class="actions">'+buttons(derived)+'</div>':''}<p>Hằng số và vật liệu</p><div class="actions">${buttons([['RHO','Khối lượng riêng','kg/m³'],['PI','Số pi']])}</div>`;
    helper.querySelectorAll('[data-df-insert],[data-df-token],[data-df-function],[data-df-return]').forEach(el=>el.disabled=!editable(helper.dataset.dfFor));
  };
  form.addEventListener('focusin',e=>{if(formulaNames.includes(e.target.name))activate(e.target.name);});
  target.addEventListener('change',()=>activate(target.value));
  form.addEventListener('input',e=>{if(formulaNames.includes(e.target.name)||/^(fieldName|outputName)\d+$/.test(e.target.name))refresh();});
  form.addEventListener('change',e=>{if(/^(fieldName|unit)\d+$/.test(e.target.name)||['base','blankShape'].includes(e.target.name))refresh();});
  form.addEventListener('change',e=>{
    if(/^mode\d+$/.test(e.target.name)&&e.target.value==='output'){const next=draft(),i=Number(e.target.name.slice(4)),f=next.fields.splice(i,1)[0],base=f.key.replace(/0$/,'');next.unfoldOutputs??=[];next.unfoldOutputs.push({key:f.key,name:f.name,unit:'mm',formula:base!==f.key&&next.fields.some(x=>x.key===base)?base:''});dfShapeEdit(id,next);return;}
    if(/^outputMode\d+$/.test(e.target.name)&&e.target.value!=='output'){const next=draft(),i=Number(e.target.name.slice(10)),o=next.unfoldOutputs.splice(i,1)[0];next.fields.push({key:o.key,name:o.name,mode:e.target.value,unit:'mm',sample:1});dfShapeEdit(id,next);return;}
    if(e.target.matches('[data-df-output-key]')){const el=e.target,old=el.dataset.previous,key=el.value;if(old&&key&&old!==key)for(const name of formulaNames){const input=form.elements.namedItem(name);input.value=input.value.replace(/\b[A-Za-z_][A-Za-z_0-9]*\b/g,token=>token===old?key:token);}const label=form.elements['outputName'+el.name.slice(9)];if(label)label.value=TPConventions.parameterName(db,key)||label.value;el.dataset.previous=key;refresh();form.dispatchEvent(new Event('input',{bubbles:true}));return;}
    if(!e.target.matches('[data-df-parameter]'))return;
    const el=e.target,old=el.dataset.previous,key=el.value,index=el.name.slice(3),item=dfParameterChoices(read(new FormData(form)).fields).find(x=>x.name===key);
    if(item){form.elements['fieldName'+index].value=item.label||'';form.elements['unit'+index].value=item.unit;}
    if(old&&key&&old!==key)for(const name of formulaNames){const input=form.elements.namedItem(name),source=input.value;input.value=source.replace(/[A-Za-z_][A-Za-z_0-9]*/g,(token,offset)=>token===old&&!/^\s*\(/.test(source.slice(offset+token.length))?key:token);}
    el.dataset.previous=key;refresh();form.dispatchEvent(new Event('input',{bubbles:true}));
  });
  form.addEventListener('click',e=>{
    const outputEdit=e.target.closest('[data-df-edit-output]');
    if(outputEdit){const input=form.elements.namedItem(outputEdit.dataset.dfEditOutput);input?.scrollIntoView({block:'center'});input?.focus({preventScroll:true});return;}
    const opener=e.target.closest('[data-df-open]');
    if(opener){activate(opener.dataset.dfOpen);helper.scrollIntoView({block:'center'});target.focus({preventScroll:true});return;}
    if(e.target.closest('[data-df-return]')){form.elements.namedItem(helper.dataset.dfFor)?.focus();return;}
    const insert=e.target.closest('[data-df-insert],[data-df-token],[data-df-function]');
    if(insert){
      const active=form.elements.namedItem(insert.closest('[data-df-for]').dataset.dfFor);
      if(!active||!editable(active.name))return;
      const start=active.selectionStart,end=active.selectionEnd,selected=active.value.slice(start,end);let text=insert.dataset.dfInsert??insert.dataset.dfToken;
      if(insert.dataset.dfFunction){const name=insert.dataset.dfFunction,extra=['ROUND','ROUNDUP','ROUNDDOWN','POW'].includes(name)?', 2':name==='IF'?', , ':name==='CLAMP'?', 0, 1':['MIN','MAX','SUM','AVG','MOD','DIV'].includes(name)?', ':'';text=name+'('+(name==='PI'?'':selected+extra)+')';}
      active.setRangeText(text,start,end,'end');if(insert.dataset.dfFunction&&!selected&&insert.dataset.dfFunction!=='PI')active.setSelectionRange(start+insert.dataset.dfFunction.length+1,start+insert.dataset.dfFunction.length+1);active.dispatchEvent(new Event('input',{bubbles:true}));active.focus({preventScroll:true});
    }
    if(e.target.id!=='df-save-parameter')return;
    try{
      const item={name:form.elements.dfNewKey.value.trim(),label:form.elements.dfNewLabel.value.trim(),unit:form.elements.dfNewUnit.value};
      if(!/^[A-Za-z][A-Za-z0-9_]{0,23}$/.test(item.name)||['RHO','PI','BW','SA','CW','CA','PHOI_POLY_L','PHOI_POLY_W','PHOI_POLY_S','PHOI_D','PHOI_R','KL_DV','DT_DV','constructor','prototype'].includes(item.name))throw Error('Ký hiệu cần bắt đầu bằng chữ, tối đa 24 chữ, số hoặc dấu gạch dưới; không dùng ký hiệu dành sẵn trong công thức.');
      if(form.elements.dfNewMode.value==='output'&&item.unit!=='mm')throw Error('Kích thước khai triển dùng đơn vị mm');const next=draft(),trial=C.copy(db);TPConventions.save(trial,'parameters',item);
      dfCatalogWrite(()=>TPConventions.save(db,'parameters',item));
      if(form.elements.dfNewMode.value==='output'){if(item.unit!=='mm')throw Error('Kích thước khai triển dùng đơn vị mm');next.unfoldOutputs??=[];next.unfoldOutputs.push({key:item.name,name:item.label,unit:'mm',formula:''});}else {const field={key:item.name,name:item.label,unit:item.unit,mode:'input',sample:1},empty=next.fields.findIndex(f=>!f.key);
      if(empty>=0)next.fields[empty]={...next.fields[empty],...field};else if(next.fields.length<24)next.fields.push(field);}
      dfShapeEdit(id,next);toast('Đã lưu thông số vào danh mục');
    }catch(error){$('#df-parameter-error').textContent=error.message;}
  });
  refresh();
}
function dfFormulaToolButton(key){return `<button type="button" class="button small df-tool-link" data-df-open="${key}" aria-controls="definition-formula-tools">Bộ công thức</button>`;}
function dfFormulaTools(){
  const names={MIN:'Giá trị nhỏ nhất',MAX:'Giá trị lớn nhất',SUM:'Tổng',AVG:'Trung bình',ROUND:'Làm tròn',ROUNDUP:'Làm tròn ra xa 0',ROUNDDOWN:'Làm tròn về 0',CEIL:'Số nguyên phía trên',FLOOR:'Số nguyên phía dưới',SQRT:'Căn bậc hai',ABS:'Giá trị tuyệt đối',POW:'Lũy thừa',MOD:'Số dư phép chia',CLAMP:'Giới hạn trong khoảng',IF:'Nếu điều kiện đúng/sai',SIGN:'Dấu của số',SIN:'Sin (radian)',COS:'Cos (radian)',TAN:'Tan (radian)',DIV:'Chia lấy phần nguyên',PI:'Số pi'};
  return `<details id="definition-formula-tools" class="df-formula-tools" data-df-for="length"><summary>Biến, phép tính và hàm · dùng chung</summary><div class="form-grid"><label class="field"><span>Chèn vào công thức</span><select data-df-target aria-label="Chèn vào công thức"></select></label><button type="button" class="button small" data-df-return>Trở về ô công thức</button></div><output data-df-active-expression aria-live="polite"></output><p class="help-text">Chọn ô công thức hoặc chọn mục ở trên. Các nút chèn tại con trỏ, thay phần đang chọn; nút hàm bọc phần đang chọn. Kích thước khai triển cập nhật theo các dòng đã khai.</p><div data-df-variables></div><p>Phép tính</p><div class="actions df-math-operators">${['+','-','*','/','^','(',')','.',',','100','1000','1000000','>','<','>=','<=','==','!='].map(x=>`<button type="button" class="button small" data-df-token="${esc(x)}">${esc(x)}</button>`).join('')}</div><p>Hàm tính toán</p><p class="help-text">Ngăn cách đối số bằng dấu phẩy; số thập phân dùng dấu chấm. Ví dụ MAX(L, W), ROUND(L, 2), IF(L &gt; 1000, L + 20, L). SIN/COS/TAN dùng radian.</p><div class="actions">${Object.entries(names).map(([name,label])=>`<button type="button" class="button small" data-df-function="${name}" title="${label}">${name}()</button>`).join('')}</div></details>`;

}
function dfStockMode(form){
 const sheet=form.elements.base.value==='sheet',stock=form.elements.testStockW,width=form.elements.width;
 stock.required=sheet;stock.disabled=!sheet;stock.closest('label').hidden=!sheet;
 const row=form.querySelector('[data-df-calculation="width"]');row.hidden=!sheet;
 if(!sheet){if(!width.readOnly)width.dataset.sheetValue=width.value;width.value='0';}else if(width.readOnly)width.value=width.dataset.sheetValue||'W';
 width.readOnly=!sheet;
 const nesting=form.elements.nesting;if(nesting&&nesting.type!=='hidden'){nesting.disabled=!sheet;nesting.closest('label').hidden=!sheet;if(!sheet)nesting.value='bounding';}
}
function dfExamples(){const kinds=['rectangle','circle','triangle-sides','triangle','trapezoid','rhombus','round','box','pipe','angle','table'];openDialog('Mẫu khai báo và đối chiếu khổ chuẩn',`<p>Mẫu minh họa để kiểm cách khai. Chọn Mở mẫu để xem toàn bộ thông số, công thức và kết quả; sửa theo thực tế trước khi lưu vào danh mục.</p><div class="table-scroll"><table><thead><tr><th>Trường hợp</th><th>Cách khai</th><th>Khổ mua thử (mm)</th><th></th></tr></thead><tbody>${kinds.map(kind=>{const d=DFC().example(kind);return `<tr><td>${esc(d.blankShapeName)}</td><td>${kind==='table'?'KM, AM theo bảng kê từng mã':d.fields.map(f=>esc(f.key)+' ('+esc(f.unit)+')').join(', ')}</td><td>${d._testStockL}${d.base==='sheet'?' × '+d._testStockW:''}</td><td>${dfButton('Mở mẫu','example',kind)}</td></tr>`;}).join('')}</tbody></table></div><p>Số bảng kê là giả lập để thử, không phải tiêu chuẩn thép. Công thức tiết diện lý tưởng chưa gồm bo góc/dung sai. Sau Lưu phiên bản, tạo mã vật tư theo quy ước rồi khai chiều dài/kích thước cắt tại báo giá.</p>`);$('#dialog').classList.add('wide-dialog');}
function dfExampleTools(){return `<details data-df-examples><summary>Mẫu khai báo tấm và thanh — mở để thử</summary><p>Mỗi mẫu có thông số, công thức, khổ mua và số lượng kiểm thử. Chỉ điền vào bản đang sửa; Lưu phiên bản mới ghi danh mục.</p><div class="form-grid">${select('Trường hợp mẫu','declarationExample',[['rectangle','Tấm chữ nhật — dài/rộng'],['circle','Tấm tròn — đường kính'],['triangle','Tấm tam giác vuông — đáy/cao'],['triangle-sides','Tấm tam giác — ba cạnh'],['trapezoid','Tấm hình thang — hai đáy/cao'],['rhombus','Tấm hình thoi — hai đường chéo'],['round','Thanh tròn đặc — công thức'],['box','Thanh hộp chữ nhật — công thức'],['pipe','Ống tròn — công thức'],['angle','Thanh góc L — công thức'],['table','Thanh định hình — bảng kê kg/m, m²/m']],'round')}<button type="button" class="button" data-df-example-apply>Điền mẫu và kiểm thử</button></div><p>Theo công thức: khai kích thước tiết diện cố định tại mã, chiều dài cắt tại báo giá. Theo bảng kê: nhập KM (kg/m), AM (m²/m) của từng mã, rồi nhân chiều dài cắt; không tự suy đoán số liệu bảng tra.</p></details>`;}
function dfAllowance(form,d,v){const el=form.querySelector('[data-df-allowance]');if(!el)return;if(!v?.allowance){el.innerHTML='<p>Chưa đủ căn cứ đối chiếu hao hụt. Kiểm tra công thức phôi và khổ mua; diện tích phôi không được vượt diện tích bao.</p>';return;}const a=v.allowance,sheet=d.base==='sheet',unit=sheet?'m²':'m';el.innerHTML=`${v.g.polygon?`<figure><svg data-df-polygon-preview viewBox="0 0 ${v.g.length} ${v.g.width}" style="width:100%;max-width:400px;height:200px" role="img" aria-label="Biên dạng đa giác theo các cạnh đã khai"><polygon points="${v.g.polygon.map(p=>p.join(',')).join(' ')}" fill="#d8e9f5" stroke="#315776" stroke-width="2" vector-effect="non-scaling-stroke"/></svg><figcaption>${v.g.sideLengths.map((x,i)=>'C0'+(i+1)+' = '+num(x)).join('; ')} mm · Diện tích ${num(v.g.blankArea,6)} m² / phôi</figcaption></figure>`:''}<h3>Đối chiếu ${sheet?'tấm':'thanh'} chuẩn</h3><p>${num(v.count)} chi tiết → <strong>${v.stocks} ${sheet?'tấm':'thanh'}</strong> khổ ${num(v.stockL)}${sheet?' × '+num(v.stockW):''} mm; mạch cắt ${num(v.kerf)} mm.</p><table><tbody><tr><th>Phôi thực theo công thức</th><td>${num(a.netMeasure,6)} ${unit}</td></tr><tr><th>Lượng mua nguyên khổ</th><td>${num(a.purchasedMeasure,6)} ${unit}</td></tr>${sheet?`<tr><th>Phần ngoài phôi trong khổ ghép / bao</th><td>${num(a.shapeOffcut,6)} ${unit}</td></tr>`:''}<tr><th>Phần dư ngoài khổ bao + mạch cắt</th><td>${num(a.stockOffcut,6)} ${unit}</td></tr><tr><th>Tổng chênh mua − phôi</th><td>${num(a.remaining,6)} ${unit}</td></tr><tr><th>Hao hụt trước tận dụng</th><td data-df-loss>${num(a.stockPercent,4)}%</td></tr><tr><th>Phần chưa sử dụng trên lượng mua</th><td>${num(a.stockPercent,4)}%</td></tr></tbody></table><p>Hao hụt trước tận dụng = (mua − phôi) / mua × 100%. Khi chọn phần tận dụng trong báo giá, phần đó được trừ khỏi cả phần dư và lượng mua để tính lại tỷ lệ. Phần chênh gồm dư có thể tận dụng, chưa phải toàn bộ phế liệu. Không cộng thêm % lần nữa nếu tính vật tư theo nguyên khổ mua.</p><p>${v.layout.mode==='right-triangle'?'Tam giác vuông: ghép cùng kích thước bằng quay 180°, có khe cắt; số lẻ hoặc cặp không vừa khổ xếp riêng. Phần ngoài phôi gồm khe cắt và đệm của khổ ghép.':v.layout.mode==='circle'?'Tấm tròn: so sánh hàng thẳng và so le ở hai hướng tấm, cùng khoảng cách mạch cắt. Nhiều đường kính: so với phương án khổ bao ghép chung; chỉ dải dư chữ nhật bên ngoài được chọn tận dụng.':'Xếp theo khổ chữ nhật bao ngoài hoặc chiều dài thanh; chưa ghép sát biên dạng cong.'} Đổi kích thước, số lượng hoặc mạch cắt sẽ tính lại. Đây là phương án tham khảo, chưa bảo đảm tối ưu toàn cục.</p>${['right-triangle','circle'].includes(v.layout.mode)?`<div class="notice" data-df-triangle-comparison><strong>Đối chiếu cùng dữ liệu</strong><p>Xếp riêng khổ bao: ${v.layout.boundingStockCount} tấm. Phương án đang dùng: ${v.stocks} tấm; ${v.layout.mode==='circle'?'xếp theo đường kính thực':v.layout.pairCount+' cặp và '+v.layout.singleCount+' phôi lẻ'}.</p><p>Hao hụt trước tận dụng: khổ bao ${num((1-a.netMeasure/(v.layout.boundingPurchased/1e6))*100,4)}% → phương án đang dùng ${num(a.stockPercent,4)}%. Không cộng thêm % khi đã tính mua nguyên khổ.</p></div>`:''}<details><summary>Xem sơ đồ sắp phôi</summary>${v.layout.stocks.slice(0,20).map((stock,i)=>stockMap({spec:{shape:sheet?'sheet':'profile'},layout:v.layout,remnants:[]},stock,i)).join('')}${v.stocks>20?'<p>Hiển thị 20 khổ đầu.</p>':''}</details>`;}
function dfTrialInputs(d){return `<h3>Dữ liệu kiểm thử</h3><div class="form-grid">${field('RHO · Khối lượng riêng thử (kg/m³)','testDensity',d._testDensity??7850,'number','min="1" step="any" required')}${field('Dài khổ mua thử (mm)','testStockL',d._testStockL??6000,'number','min="1" max="100000" required')}${field('Rộng khổ mua thử (mm; chỉ dùng cho tấm)','testStockW',d._testStockW??1220,'number','min="1" max="100000" required')}${field('Số lượng chi tiết thử','testCount',d._testCount??1,'number','min="1" max="5000" step="1" required')}${field('Mạch cắt thử (mm)','testKerf',d._testKerf??0,'number','min="0" step="any" required')}</div>`;}
function dfDeclaredCalculations(d,v){
 const vars=v?.vars||{},substitute=source=>source.replace(/[A-Za-z_][A-Za-z_0-9]*/g,(name,offset)=>Object.hasOwn(vars,name)&&!/^\s*\(/.test(source.slice(offset+name.length))?'('+num(vars[name],6)+')':name);
 return (d.unfoldOutputs||[]).map((o,i)=>`<tr data-df-declared="${esc(o.key)}"><td>${esc(o.key)} · ${esc(o.name||'Kích thước khai triển')}<small>mm</small></td><td><code>${esc(o.key)} = ${esc(o.formula)}</code> <button type="button" class="button small" data-df-edit-output="outputFormula${i}">Sửa công thức</button></td><td><code>${v?esc(substitute(o.formula)):'—'}</code></td><td><output data-df-declared-result="${esc(o.key)}" ${v?`data-value="${v.vars[o.key]}"`:''}>${v?num(v.vars[o.key],6):'—'}</output></td></tr>`).join('');
}
function dfSurfaceHelp(d){
 const basis=d.base==='sheet'?'Với tấm, A = 1 m²/m² nghĩa là mỗi 1 m² tấm được tính là 1 m² diện tích vật tư.':'Với thanh, A có đơn vị m²/m: diện tích vật tư trên 1 mét dài. Thép định hình có thể lấy định mức AM theo mã vật tư.';
 const use=!(d.blankSurface||'').trim()||/\bDT_DV\b/.test(d.blankSurface)?'Công thức diện tích phôi dùng định mức này qua ký hiệu DT_DV.':'Công thức diện tích phôi đang khai riêng, không dùng A (DT_DV).';
 return basis+' A dùng để tính diện tích vật tư mua theo khổ. '+use+' Diện tích của một chi tiết xem ở dòng “Diện tích phôi sản phẩm” bên dưới. Diện tích sơn / gia công khai riêng tại công đoạn.';
}
function dfFormulaTable(d){
 const declared=!!d.unfoldOutputs?.length,symbols=DFC().unfoldSymbols(d),formulas=DFC().editorFormulas(d);
 const dimensions=[['length',declared?'Dài khổ bao để xếp phôi':symbols.length+' · Dài khai triển','mm'],['width',declared?'Rộng khổ bao để xếp phôi':symbols.width+' · Rộng khai triển','mm']];
 const quantities=[['mass','K · Khối lượng vật tư trên đơn vị',d.base==='sheet'?'kg/m²':'kg/m'],['surface','A · Định mức diện tích vật tư',d.base==='sheet'?'m²/m²':'m²/m'],['blankMass','Khối lượng phôi sản phẩm','kg / chi tiết'],['blankSurface','Diện tích phôi sản phẩm','m² / chi tiết']];
 const header='<thead><tr><th>Đại lượng</th><th>Công thức tính</th><th>Thay số kiểm thử</th><th>Kết quả</th></tr></thead>';
 const row=([key,label,unit])=>`<tr data-df-calculation="${key}"><td>${label}<small data-df-unit="${key}">${unit}</small></td><td><div class="df-equation">${['length','width'].includes(key)?`<span data-df-output-symbol="${key}">${esc(symbols[key])} =</span>`:''}${field(label,key,formulas[key]??d[key],'text',key.startsWith('blank')?'':'required')}</div>${dfFormulaToolButton(key)}${key==='surface'?`<p class="help-text" data-df-surface-help>${esc(dfSurfaceHelp(d))}</p>`:''}</td><td><code data-df-substitute="${key}"></code></td><td><output data-df-result="${key}"></output></td></tr>`;
 return `<h3>Công thức và kết quả kiểm thử</h3><p class="help-text">${declared?'Kích thước khai triển hiển thị theo các ký hiệu đã khai ở trên. Với đa giác, mỗi cạnh có công thức và kết quả riêng; khổ bao để xếp phôi nằm trong mục bên dưới.':esc(symbols.length)+' và '+esc(symbols.width)+' là kết quả khai triển (mm). Nhập biểu thức ở vế phải.'}</p><p class="help-text">K và A là định mức trên đơn vị vật tư; phôi tính theo công thức khối lượng và diện tích đã khai. Với thép định hình, KM và AM là thông số cố định theo mã.</p><div class="table-scroll"><table id="definition-calculations">${header}<tbody data-df-declared-calculations>${dfDeclaredCalculations(d,null)}</tbody><tbody>${[...(declared?[]:dimensions),...quantities].map(row).join('')}${[['stocks','Số khổ vật tư mua','khổ'],['totalKg','Khối lượng phôi — toàn bộ số lượng thử','kg'],['totalArea','Diện tích phôi — toàn bộ số lượng thử','m²'],['buyKg','Khối lượng vật tư mua','kg'],['buyArea','Diện tích vật tư mua','m²']].map(([key,label,unit])=>`<tr data-df-calculation="${key}"><td>${label}<small>${unit}</small></td><td data-df-explanation="${key}"></td><td><code data-df-substitute="${key}"></code></td><td><output data-df-result="${key}"></output></td></tr>`).join('')}</tbody></table></div>${declared?`<details data-df-envelope><summary>Khổ bao để xếp phôi · dài / rộng</summary><p>Khổ bao phục vụ bố trí và tính số tấm mua. Kích thước các cạnh hoặc đường kính được khai riêng trong bảng trên.</p><div class="table-scroll"><table>${header}<tbody>${dimensions.map(row).join('')}</tbody></table></div></details>`:''}`;
}
function dfShowTrial(form,d,v,error){
  form.querySelector('[data-df-declared-calculations]').innerHTML=dfDeclaredCalculations(d,v);
  form.querySelector('[data-df-surface-help]').textContent=dfSurfaceHelp(d);
  const unit=d.base==='sheet'?['kg/m²','m²/m²']:['kg/m','m²/m'];
  for(const [i,key]of ['mass','surface'].entries())form.querySelector('[data-df-unit="'+key+'"]').textContent=unit[i];
  form.querySelector('[data-df-unit="width"]').textContent=d.base==='sheet'?'mm':'Thanh: để 0';
  const labels={stocks:'Xếp phôi theo khổ mua và mạch cắt',totalKg:'Khối lượng một phôi × số lượng',totalArea:'Diện tích một phôi × số lượng',buyKg:'Số khổ × dài khổ / 1.000'+(d.base==='sheet'?' × rộng khổ / 1.000':'')+' × K',buyArea:'Số khổ × dài khổ / 1.000'+(d.base==='sheet'?' × rộng khổ / 1.000':'')+' × A'};
  for(const [key,label]of Object.entries(labels))form.querySelector('[data-df-explanation="'+key+'"]').textContent=label;
  for(const el of form.querySelectorAll('[data-df-substitute],[data-df-result]')){el.textContent='—';delete el.dataset.value;}
  for(const [i,o] of (d.unfoldOutputs||[]).entries()){const el=form.querySelector('[data-df-output-result="'+i+'"]');if(el)el.textContent=v?o.key+' = '+num(v.vars[o.key],6)+' mm':'—';}
  if(error){form.querySelector('#definition-calculations').dataset.valid='false';return;}
  const outputs={length:v.g.length,width:v.g.width,mass:v.rates.mass,surface:v.rates.surface,blankMass:v.g.weight,blankSurface:v.g.blankArea,stocks:v.stocks,totalKg:v.totalKg,totalArea:v.totalArea,buyKg:v.buyKg,buyArea:v.buyArea};
  const vars=v.vars,expressions={...d,...DFC().blankFormulas(d)},substitute=source=>source.replace(/[A-Za-z_][A-Za-z_0-9]*/g,(name,offset)=>Object.hasOwn(vars,name)&&!/^\s*\(/.test(source.slice(offset+name.length))?'('+num(vars[name],6)+')':name);
  for(const key of ['length','width','mass','surface','blankMass','blankSurface'])form.querySelector('[data-df-substitute="'+key+'"]').textContent=substitute(expressions[key]);
  const factor=num(v.stocks)+' × '+num(v.stockL)+' / 1.000'+(d.base==='sheet'?' × '+num(v.stockW)+' / 1.000':'');
  for(const [key,text]of Object.entries({stocks:num(v.count)+' chi tiết; mạch cắt '+num(v.kerf)+' mm',totalKg:num(v.g.weight,6)+' × '+v.count,totalArea:num(v.g.blankArea,6)+' × '+v.count,buyKg:factor+' × '+num(v.rates.mass,6),buyArea:factor+' × '+num(v.rates.surface,6)}))form.querySelector('[data-df-substitute="'+key+'"]').textContent=text;
  for(const [key,value]of Object.entries(outputs)){const el=form.querySelector('[data-df-result="'+key+'"]');el.textContent=num(value,6);el.dataset.value=String(value);}
  form.querySelector('#definition-calculations').dataset.valid='true';
}
function dfPolygonCheckRow(d){
 const p=d.polygon,n=p?.sides.length;if(p?.kind!=='interior'||n<4)return '';
 const label='A'+(n-2)+' · Góc giữa cạnh '+(n-2)+' và '+(n-1)+' (độ)';
 return `<tr data-df-check-angle><td>A${n-2}</td><td>Góc đối chiếu thêm</td><td>Lưu cùng mẫu hình</td><td>độ</td><td>${field(label,'polygonCheckAngle',p.checkAngle??'','number','step="any" placeholder="Có thể bỏ trống"')}<small>Đối chiếu với hình đã dựng. Bỏ trống nếu không cần kiểm tra thêm góc này.</small></td><td></td></tr>`;
}
function dfPolygonTools(d){return `<details data-df-polygon open><summary>Khai tấm đa giác theo số cạnh</summary><div class="form-grid">${select('Cách xác định biên dạng','polygonKind',[['triangle','Tam giác theo ba cạnh'],['regular','Đa giác đều'],['interior','Cạnh và góc giữa hai cạnh'],['edges','Góc hướng từng cạnh (cách khai cũ)']],d.polygon?.kind||'triangle')}${field('Số cạnh (3–10; tam giác luôn là 3)','polygonCount',d.polygon?.sides.length||3,'number','min="3" max="10" step="1"')}<button type="button" class="button" data-df-polygon-apply>Tạo các cạnh và công thức</button></div><p>Nhập C1, C2… theo thứ tự quanh biên; C01, C02… là kích thước khai triển. Tam giác chỉ cần ba cạnh. Với bản đã có ba cạnh, chọn “Tam giác theo ba cạnh” hoặc bỏ thông số góc sẽ chuyển cách tính ngay, giữ kích thước và công thức cạnh đã nhập. Đa giác đều có các cạnh bằng nhau. Với cách khai góc giữa hai cạnh: tứ giác nhập 4 cạnh và 1 góc, ngũ giác nhập 5 cạnh và 2 góc để dựng hình. Bảng có thêm một góc đối chiếu: tứ giác là A2, ngũ giác là A3 (tổng n−2 ô góc). Góc đối chiếu có thể bỏ trống; nếu nhập thì phải khớp với các cạnh và góc đã khai. Giá trị này lưu cùng mẫu hình; tại báo giá có thể sửa trong Khai đa giác. Các góc còn lại được tính từ hình khép kín. A1 là góc giữa cạnh 1 và 2, A2 giữa cạnh 2 và 3. Góc hướng từng cạnh là cách khai cũ, đo từ trục ngang (0° sang phải, 90° lên trên). Các cạnh phải khép kín, không tự giao. Nút tạo thay thông số trong bản đang sửa; chỉ ghi khi Lưu phiên bản.</p>${d.polygon?.kind==='interior'?select('Hình khép kín (xem kết quả để chọn)','polygonBranch',[[0,'Hình 1'],[1,'Hình 2 nếu có']],d.polygon.branch||0):''}${d.polygon?.kind==='edges'&&d.polygon.sides.length===3?'<button type="button" class="button" data-df-triangle-only>Dùng ba cạnh, bỏ khai góc</button>':''}<p>Diện tích theo biên thực. Xếp phôi theo khổ bao có chừa mạch cắt; chưa tối ưu ghép sát cạnh đa giác. Ví dụ: tam giác 300–400–500 mm; lục giác đều cạnh 300 mm.</p></details>`;}
function dfSheetPresetKind(d){return d.polygon?(d.polygon.kind==='triangle'?'triangle-sides':'polygon'):({'Tấm tròn':'circle','Tấm tam giác vuông':'triangle','Tấm hình thang':'trapezoid','Tấm hình thoi':'rhombus','Tấm chữ nhật':'rectangle'}[d.blankShapeName]||'custom');}
function dfSheetPresetTools(d){return `<fieldset data-df-sheet-presets><legend>Kích thước theo hình khai triển</legend><div class="form-grid">${select('Chọn mẫu khai triển','sheetPreset',[['polygon','Đa giác · số cạnh và kích thước các cạnh'],['custom','Tự khai theo kích thước khai triển'],['trapezoid','Hình thang · hai đáy và chiều cao'],['rhombus','Hình thoi · hai đường chéo'],['rectangle','Vuông / chữ nhật · chiều dài, chiều rộng'],['circle','Tròn · đường kính D'],['triangle','Tam giác vuông · cạnh đáy L, chiều cao H'],['triangle-sides','Tam giác · ba cạnh C1, C2, C3']],dfSheetPresetKind(d))}<div><button type="button" class="button" data-df-preset-apply>Điền thông số và công thức mẫu</button></div></div><p class="help-text">Nút này thay các thông số và công thức trong bản đang sửa; bấm Lưu phiên bản mới ghi vào danh mục. “Nơi nhập” gồm cố định theo mã, nhập tại báo giá và kích thước khai triển theo công thức.</p><p class="help-text">Tấm tròn dùng D0 = D và diện tích πD0²/4. Hình thang dùng hai đáy và chiều cao; hình thoi dùng hai đường chéo. Chọn Tự khai để giữ thông số/công thức đang sửa rồi bổ sung kích thước khai triển. Kích thước dài/rộng khổ bao phục vụ tính lượng mua; cách bố trí phôi được chọn tại mục hao hụt của từng báo giá.</p></fieldset>`;}
// Repair only the editable draft; existing material and quotation snapshots stay intact.
function dfTriangleWithoutAngles(d,force=false){
 const p=d.polygon;if(!p||p.sides?.length!==3||!force&&(p.kind!=='edges'||p.angles?.length===3&&p.angles.every(k=>d.fields.some(f=>f.key===k))))return d;
 const next=C.copy(d),angles=new Set(p.angles||[]),expressions=[...Object.values(DFC().editorFormulas(d)),...(d.unfoldOutputs||[]).map(o=>o.formula)].filter(x=>typeof x==='string'),used=new Set(expressions.flatMap(x=>x.match(/[A-Za-z_][A-Za-z_0-9]*/g)||[]));
 next.polygon={kind:'triangle',sides:[...p.sides]};next.fields=next.fields.filter(f=>!angles.has(f.key)||used.has(f.key));
 return next;
}
function dfShapeEdit(id,working){
  const old=(db.shapeDefinitions||[]).find(x=>x.id===id),d=dfTriangleWithoutAngles(C.copy(working||old||{id:'QD-'+C.uid(),name:'',base:'bar',fields:[{key:'L',mode:'input',unit:'mm',sample:2000},{key:'KM',mode:'fixed',unit:'kg/m',sample:10},{key:'AM',mode:'fixed',unit:'m²/m',sample:.5}],length:'L',width:'0',mass:'KM',surface:'AM',notes:'',condition:''}));
  openDialog('Công thức tổng hợp · '+esc(d.name||'Quy ước mới'),`<p>Thông số kích thước nhập theo mm. Công thức dài/rộng trả về mm; đổi mm sang m bằng /1000, mm² sang m² bằng /1000000. RHO là kg/m³; PI là số π. Số thử chỉ để kiểm, không phải tiêu chuẩn của xưởng.</p><div class="form-grid"><input type="hidden" name="id" value="${esc(d.id)}">${select('Nhóm lớn / nhóm sản phẩm','productGroup',cvProductOptions(d.productGroup),d.productGroup||'')}${field('Nhóm chi tiết / dạng cấu kiện','name',d.name,'text','required maxlength="200"')}${select('Cách tính khổ mua','base',[['bar','Theo chiều dài thanh'],['sheet','Theo khổ tấm']],d.base)}${select('Dạng cơ sở để tính phôi','blankShape',Object.entries(C.shapes).filter(([key])=>key!=='piece').map(([key,value])=>[key,value.name]),d.blankShape||(d.base==='sheet'?'sheet':'profile'))}${field('Tên hình dạng phôi','blankShapeName',d.blankShapeName||'','text','maxlength="200" list="blank-shape-names" placeholder="Chọn gợi ý hoặc nhập hình dạng mới"')}<datalist id="blank-shape-names">${[...new Set([...Object.values(C.shapes).map(x=>x.name),...(db.shapeDefinitions||[]).map(x=>DFC().blankShapeName(x))])].map(x=>`<option value="${esc(x)}"></option>`).join('')}</datalist></div><p class="help-text">Có thể nhập tên phôi riêng (ví dụ: Tấm tròn, Thanh chữ Z). Chọn dạng cơ sở và khai công thức bên dưới phù hợp với phôi thực tế; tên mới không tự sinh công thức.</p>${dfSheetPresetTools(d)}${dfPolygonTools(d)}<input type="hidden" name="nesting" value="${esc(d.nesting||'bounding')}"><p class="help-text">Khai hình dạng và kích thước tại đây. Chọn cách xoay/ghép và chỉnh vị trí phôi trong Báo giá → Khai triển & hao hụt → Sắp xếp phôi.</p>${dfExampleTools()}<div class="table-scroll"><table id="definition-fields"><thead><tr><th>Ký hiệu</th><th>Tên / diễn giải</th><th>Nơi nhập</th><th>Đơn vị</th><th>Số thử / Công thức khai triển</th><th></th></tr></thead><tbody>${dfRows(d.fields)}${dfPolygonCheckRow(d)}${dfOutputRows(d)}</tbody></table></div>${dfButton('+ Thông số','add-field')}${dfButton('+ Kích thước khai triển','add-output')}<p class="help-text">Nơi nhập: chọn Kích thước khai triển để khai công thức ngay tại dòng (ví dụ D0 = D, L0 = L, W0 = W + 2 * H). Kết quả được tính tự động khi đổi đầu vào.</p>${dfParameterTools()}${dfFormulaTools()}${dfTrialInputs(d)}${dfFormulaTable(d)}${b1Area('Điều kiện áp dụng (cần người lập kiểm tra)','condition',d.condition)}${b1Area('Ghi chú / nguồn công thức','notes',d.notes)}<output id="definition-preview" class="notice" aria-live="polite"></output><section class="panel panel-body" data-df-allowance></section><p>Khối lượng/diện tích mua = số khổ × kích thước khổ quy về m hoặc m² × công thức trên đơn vị. Đây là lượng vật lý, không tự thay diện tích thực sự sơn/gia công. Báo giá cũ giữ phiên bản đã chọn; sửa quy ước không tự cập nhật đơn.</p>`,'Lưu phiên bản',f=>{const value=read(f);for(const k of ['_testDensity','_testStockL','_testStockW','_testCount','_testKerf'])delete value[k];evaluate(value,f);dfCatalogWrite(()=>DFC().saveShape(db,value));closeDialog();toast(Team.loaded?'Đã ghi vào bản danh mục đang sửa. Bấm Lưu danh mục chung để đồng nghiệp dùng.':'Đã lưu quy ước trên máy; đơn cũ không đổi');});
  $('#dialog').classList.add('wide-dialog');
  function read(f){const checked=String(f.get('polygonCheckAngle')??'').trim(),polygon=d.polygon?{...d.polygon}:null;if(polygon?.kind==='interior'){delete polygon.checkAngle;if(checked)polygon.checkAngle=Number(checked);}const names=new Map([...d.fields.map((x,i)=>[x.key,String(f.get('key'+i)||'').trim()]),...(d.unfoldOutputs||[]).map((x,i)=>[x.key,String(f.get('outputKey'+i)||'').trim()])]);return {...d,...(d.polygon?{polygon:{...polygon,sides:d.polygon.sides.map(k=>names.get(k)||k),...(d.polygon.angles?{angles:d.polygon.angles.map(k=>names.get(k)||k)}:{})}}:{}),id:String(f.get('id')).trim(),name:String(f.get('name')).trim(),productGroup:String(f.get('productGroup')||'').trim(),base:f.get('base'),nesting:f.get('base')==='sheet'?(f.get('nesting')||'bounding'):'bounding',blankShape:f.get('blankShape'),blankShapeName:String(f.get('blankShapeName')||'').trim(),unfoldOutputs:(d.unfoldOutputs||[]).map((o,i)=>({key:String(f.get('outputKey'+i)||'').trim(),name:String(f.get('outputName'+i)||'').trim(),unit:'mm',formula:String(f.get('outputFormula'+i)||'').trim()})),fields:d.fields.map((_,i)=>({key:String(f.get('key'+i)).trim(),name:String(f.get('fieldName'+i)||'').trim(),mode:f.get('mode'+i),unit:f.get('unit'+i),sample:Number(f.get('sample'+i))})),...Object.fromEntries(['length','width','mass','surface','blankMass','blankSurface','notes','condition'].map(k=>[k,String(f.get(k)||'').trim()]))};}
  function evaluate(value,f){if(f.get('sheetPreset')!==dfSheetPresetKind(d))throw Error('Đã đổi hình. Bấm “Tạo bảng thông số” để cập nhật các ô cần nhập trước khi lưu.');if(value.polygon?.kind==='interior')value.polygon.branch=Number(f.get('polygonBranch')||0);if(value.polygon&&(f.get('polygonKind')!==value.polygon.kind||Number(f.get('polygonCount'))!==value.polygon.sides.length))throw Error('Cách khai hoặc số cạnh đã đổi. Bấm “Tạo các cạnh và công thức” để cập nhật bảng trước khi lưu.');return DFC().trial(value,{inputs:Object.fromEntries(value.fields.map(x=>[x.key,x.sample])),density:Number(f.get('testDensity')),stockL:Number(f.get('testStockL')),stockW:Number(f.get('testStockW')),count:Number(f.get('testCount')),kerf:Number(f.get('testKerf'))});}
  const form=$('#dialog-form');form.dataset.definitionSheetPreset=dfSheetPresetKind(d);form.dataset.definitionPolygonKind=d.polygon?.kind||'';form.dataset.definitionPolygonCount=d.polygon?.sides.length||'';form.querySelector('[data-df-triangle-only]')?.addEventListener('click',()=>dfShapeEdit(id,dfTriangleWithoutAngles({...read(new FormData(form)),_testDensity:form.elements.testDensity.value,_testStockL:form.elements.testStockL.value,_testStockW:form.elements.testStockW.value,_testCount:form.elements.testCount.value,_testKerf:form.elements.testKerf.value},true)));form.elements.polygonCount.addEventListener('change',()=>{if(Number(form.elements.polygonCount.value)!==3&&form.elements.polygonKind.value==='triangle')form.elements.polygonKind.value='interior';});form.elements.polygonKind.addEventListener('change',e=>{if(form.elements.polygonKind.value==='triangle'){form.elements.polygonCount.value='3';if(d.polygon?.sides.length===3&&d.polygon.kind!=='triangle'){e.stopPropagation();dfShapeEdit(id,dfTriangleWithoutAngles({...read(new FormData(form)),_testDensity:form.elements.testDensity.value,_testStockL:form.elements.testStockL.value,_testStockW:form.elements.testStockW.value,_testCount:form.elements.testCount.value,_testKerf:form.elements.testKerf.value},true));}}});form.querySelector('[data-df-polygon-apply]').onclick=()=>{try{dfShapeEdit(id,{...read(new FormData(form)),...DFC().polygonPreset(form.elements.polygonKind.value,form.elements.polygonCount.value)});}catch(error){toast(error.message);}};form.querySelector('[data-df-example-apply]').onclick=()=>{const next={...read(new FormData(form)),...DFC().example(form.elements.declarationExample.value)};dfShapeEdit(id,next);};form.querySelector('[data-df-preset-apply]').onclick=()=>{const next={...read(new FormData(form)),...(form.elements.sheetPreset.value==='polygon'?DFC().polygonPreset(form.elements.polygonKind.value,form.elements.polygonCount.value):form.elements.sheetPreset.value==='custom'?{base:'sheet',blankShape:'sheet',blankShapeName:'Tấm tự khai',nesting:'bounding'}:DFC().sheetPreset(form.elements.sheetPreset.value))};dfShapeEdit(id,next);};dfBindParameters(form,id,read);form.elements.blankShape.addEventListener('change',()=>{form.elements.base.value=form.elements.blankShape.value==='sheet'?'sheet':'bar';});form.elements.base.addEventListener('change',()=>{form.elements.blankShape.value=form.elements.base.value==='sheet'?'sheet':'profile';});const preview=()=>{dfStockMode(form);const value=read(new FormData(form));$('#dialog-title').textContent='Công thức tổng hợp · '+(value.name||'Quy ước mới');try{const v=evaluate(value,new FormData(form));dfShowTrial(form,value,v);dfAllowance(form,value,v);$('#definition-preview').textContent=`${value.unfoldOutputs?.length?'Kích thước khai triển: '+value.unfoldOutputs.map(o=>o.key+' = '+num(v.vars[o.key],6)).join('; ')+' mm. Khổ bao xếp phôi: ':'Khai triển một chi tiết: '}${num(v.g.length)}${v.g.width?' × '+num(v.g.width):''} mm.\nKhối lượng phôi: ${num(v.g.weight,4)} kg. Diện tích phôi: ${num(v.g.blankArea,4)} m².\nVật tư mua (${v.stocks} khổ): ${num(v.buyKg,4)} kg; ${num(v.buyArea,4)} m².`;$('#definition-preview').dataset.valid='true';$('#dialog-error').hidden=true;}catch(e){dfShowTrial(form,value,null,e);dfAllowance(form,value,null);$('#definition-preview').textContent=e.message;$('#definition-preview').dataset.valid='false';}};form.addEventListener('input',preview);form.addEventListener('change',preview);form.addEventListener('click',e=>{const b=e.target.closest('[data-definition]');if(!b||!['add-field','drop-field','add-output','drop-output'].includes(b.dataset.definition))return;const next={...read(new FormData(form)),_testDensity:form.elements.testDensity.value,_testStockL:form.elements.testStockL.value,_testStockW:form.elements.testStockW.value,_testCount:form.elements.testCount.value,_testKerf:form.elements.testKerf.value};if(b.dataset.definition==='add-output'){next.unfoldOutputs??=[];next.unfoldOutputs.push({key:'',name:'',unit:'mm',formula:''});}else if(b.dataset.definition==='drop-output')next.unfoldOutputs.splice(Number(b.dataset.id),1);else if(b.dataset.definition==='add-field')next.fields.push({key:'',name:'',mode:'input',unit:'mm',sample:1});else next.fields.splice(Number(b.dataset.id),1);dfShapeEdit(id,next);});preview();
}
function dfRules(){return `<section class="panel"><div class="panel-head"><div><h2>Quy ước hình dạng do mình khai</h2><p>Phân biệt thông số cố định và nhập tại báo giá; công thức có phiên bản.</p></div>${dfButton('+ Quy ước hình dạng','shape-new')}</div><div class="table-scroll"><table><thead><tr><th>Mã / tên</th><th>Thông số</th><th>Phiên bản</th><th></th></tr></thead><tbody>${(db.shapeDefinitions||[]).map(d=>`<tr><td>${esc(d.id)}<small>${esc(d.name)}</small></td><td>${d.fields.map(f=>esc(f.key)+' · '+(f.mode==='fixed'?'cố định':'nhập tại đơn')+' ('+esc(f.unit)+')').join('<br>')}</td><td>${d.version||1}</td><td>${dfButton('Sửa & thử','shape-edit',d.id)}${dfButton('Tạo mã vật tư theo quy ước','shape-material',d.id)}</td></tr>`).join('')||'<tr><td colspan="4">Chưa khai quy ước riêng. Các quy ước có sẵn ở phía dưới vẫn dùng được.</td></tr>'}</tbody></table></div></section>`;}
function dfMaterial(defId,materialId){
  const d=(db.shapeDefinitions||[]).find(x=>x.id===defId),old=db.materials.find(x=>x.id===materialId);if(!d)throw Error('Không có quy ước đã chọn');
  const m=old||{id:'',name:d.name,substance:'Thép',price:0,unit:'kg',props:{}};
  openDialog('Mã vật tư theo '+esc(d.name),`<p>Quy ước ${esc(d.id)} · phiên bản ${d.version||1}. ${esc(d.condition||'Không có ghi chú điều kiện riêng.')}</p><div class="form-grid">${field('Mã vật tư','id',m.id,'text',`required ${old?'readonly':''}`)}${field('Tên vật tư','name',m.name,'text','required maxlength="200"')}${select('Vật liệu','substance',TPConventions.entries(db,'substances').map(x=>x.name),m.substance)}${select('Mác vật liệu','grade',[['','Không áp dụng']],m.grade||'')}${select('Đặc tính','characteristic',[['','Không áp dụng']],m.characteristic||'')}${select('Đơn vị giá','unit',d.base==='sheet'?['kg','m²','tấm']:['kg','m','thanh'],m.unit)}${field('Đơn giá','price',m.price,'number','min="0" step="any" required')}</div><h3>Thông số cố định của mã</h3><div class="form-grid">${d.fields.filter(f=>f.mode==='fixed').map(f=>field(f.key+' — '+(f.name||TPConventions.parameterName(db,f.key))+' ('+f.unit+')',f.key,m.props[f.key]??f.sample,'number','min="0" step="any" required')).join('')}</div><p>Thông số cần nhập ở báo giá: ${d.fields.filter(f=>f.mode==='input').map(f=>esc(f.key)+' ('+esc(f.unit)+')').join(', ')}. Khi tạo dòng, số thử được điền sẵn để chỉnh lại theo đơn thật.</p><p>Khổ mua khai tại Thẻ kho trong danh mục vật tư.</p><p>Khối lượng riêng lấy theo vật liệu đã chọn. Mác và đặc tính được lọc theo vật liệu đó. Đơn đã dùng mã này giữ nguyên.</p>`,'Lưu mã vật tư',f=>{const id=String(f.get('id')).trim();if(!old&&db.materials.some(x=>x.id===id))throw Error('Mã đã tồn tại');const substance=TPConventions.entries(db,'substances').find(x=>x.name===f.get('substance'));if(!substance)throw Error('Chọn vật liệu');const value=DFC().applyShape({...m,id,name:String(f.get('name')).trim(),group:m.group||C.groups[0],substance:substance.name,density:substance.density,grade:String(f.get('grade')||''),characteristic:String(f.get('characteristic')||''),unit:f.get('unit'),price:Number(f.get('price')),stockL:m.stockL||0,stockW:m.stockW||0},d,Object.fromEntries(f));TPIntake.validateMaterial(db,value);DFC().testShape(d,{...Object.fromEntries(d.fields.map(x=>[x.key,x.sample])),...value.props},value.density);dfCatalogWrite(()=>{if(old)Object.assign(old,value);else db.materials.push(value);});closeDialog();toast('Đã lưu mã theo quy ước; đơn đang có giữ nguyên');});$('#dialog').classList.add('wide-dialog');
  const form=$('#dialog-form'),related=reset=>{for(const [key,kind]of [['grade','grades'],['characteristic','characteristics']]){const value=reset?'':m[key]||'';form.elements[key].innerHTML=[['','Không áp dụng'],...TPIntake.materialChoices(db,kind,form.elements.substance.value).map(x=>[x.name,x.name])].map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('');}};related(false);form.elements.substance.addEventListener('change',()=>related(true));
}
function dfStockList(){openDialog('Khổ mua chuẩn dùng chung',`<p>Khổ mua tách khỏi quy cách mã vật tư. Ghi máy/xưởng có thể dùng khổ này; không tự đặt ngưỡng năng lực máy khi chưa có dữ liệu.</p>${dfButton('+ Khổ chuẩn','stock-new')}<div class="table-scroll"><table><thead><tr><th>Mã / tên</th><th>Khổ (mm)</th><th>Xưởng / máy</th><th>Trạng thái</th><th></th></tr></thead><tbody>${(db.stockSizes||[]).map(s=>`<tr><td>${esc(s.id)}<small>${esc(s.name)}</small></td><td>${num(s.length)}${s.base==='sheet'?' × '+num(s.width):''}</td><td>${esc(s.workshop||'Chưa khai')} / ${esc(s.machine||'Chưa khai')}</td><td>${s.active===false?'Ngừng chọn mới':'Đang dùng'}</td><td>${dfButton('Sửa','stock-edit',s.id)}</td></tr>`).join('')||'<tr><td colspan="5">Chưa khai khổ dùng chung.</td></tr>'}</tbody></table></div>`);$('#dialog').classList.add('wide-dialog');}
function dfStockEdit(id){const s=(db.stockSizes||[]).find(x=>x.id===id)||{id:'KHO-'+C.uid(),name:'',base:'bar',length:'',width:'',workshop:'',machine:'',active:true};openDialog('Khai khổ mua chuẩn',`<div class="form-grid"><input type="hidden" name="id" value="${esc(s.id)}">${field('Tên khổ','name',s.name,'text','required')}${select('Dạng','base',[['bar','Thanh'],['sheet','Tấm']],s.base)}${field('Dài (mm)','length',s.length,'number','min="1" max="100000" required')}${field('Rộng (mm; tấm mới cần)','width',s.width,'number','min="0" max="100000"')}${field('Xưởng áp dụng','workshop',s.workshop)}${field('Máy / công đoạn phù hợp','machine',s.machine)}</div><label class="pa-checkbox"><input name="active" type="checkbox" ${s.active!==false?'checked':''}> Cho chọn ở đơn mới</label><p>Sửa hoặc ngừng dùng không đổi khổ đã chụp trong đơn cũ.</p>`,'Lưu khổ chuẩn',f=>{const value={id:String(f.get('id')).trim(),name:String(f.get('name')).trim(),base:f.get('base'),length:Number(f.get('length')),width:Number(f.get('width')||0),workshop:String(f.get('workshop')).trim(),machine:String(f.get('machine')).trim(),active:f.has('active')};if(!id&&(db.stockSizes||[]).some(x=>x.id===value.id))throw Error('Mã khổ đã có');DFC().validateStock(value);dfCatalogWrite(()=>DFC().saveStock(db,value));closeDialog();dfStockList();toast(Team.loaded?'Đã ghi khổ vào bản đang sửa. Bấm Lưu danh mục chung để lưu lên máy chủ.':'Đã lưu khổ chuẩn trên máy.');});}
function dfChooseStock(id){const n=C.findNode(db.quote.products,id);if(!n||n.draftMaterial||n.spec.shape==='piece')return;const m=n.spec,options=DFC().stocks(db,m);b1Stock(id);const form=$('#dialog-form');form.insertAdjacentHTML('afterbegin',`${select('Khổ dùng chung theo máy/xưởng','sharedStock',[['','Giữ khổ đang nhập / đặt riêng'],...options.map(s=>[s.id,s.name+' · '+s.length+(s.base==='sheet'?' × '+s.width:'')+' mm · '+(s.workshop||'chưa ghi xưởng')+' / '+(s.machine||'chưa ghi máy')])],'')}<p class="help-text">Danh sách chỉ gồm cùng dạng tấm/thanh. Sau khi chọn vẫn được nhập khổ riêng. Kiểm tra máy/xưởng phù hợp đơn thực tế.</p>`);form.elements.sharedStock.onchange=()=>{const s=options.find(s=>s.id===form.elements.sharedStock.value);if(s){form.elements.stockL.value=s.length;if(m.shape==='sheet')form.elements.stockW.value=s.width;}};
  // Record the selection only after the existing stock-fit validation has succeeded.
  const original=form.onsubmit;form.onsubmit=async e=>{const s=options.find(s=>s.id===form.elements.sharedStock.value),l=Number(form.elements.stockL.value),w=m.shape==='sheet'?Number(form.elements.stockW.value):0,source=s&&l===s.length&&(m.shape!=='sheet'||w===s.width)?C.copy(s):!s&&l===m.stockL&&(m.shape!=='sheet'||w===m.stockW)&&m.stockSource?C.copy(m.stockSource):{name:'Khổ đặt riêng',length:l,width:w,...(s?{from:s.id}:{})};await original.call(form,e);if(!$('#dialog').open&&n.spec.stockL===l&&(m.shape!=='sheet'||n.spec.stockW===w)){mutation(()=>{n.spec.stockSource=source;});}};
}
function dfDraft(parentId){const parent=C.findNode(db.quote.products,parentId);if(!parent||parent.kind==='material')return;openDialog('Thêm dòng vật tư nháp',`${field('Tên / mô tả tạm','name','Vật tư chưa chọn mã','text','required')}${field('Số lượng / một cấp cha','qty',1,'number','min="0.001" max="5000" step="any" required')}<p>Có thể lưu rồi chọn mã sau. Dòng này chưa có giá, chưa được duyệt/xuất chào giá chính thức.</p>`,'Thêm dòng nháp',f=>{inWritable();const n=DFC().draft(String(f.get('name')).trim(),Number(f.get('qty')));saveAndClose(()=>{parent.children.push(n);selected=n.id;});});}
function dfAssign(id){const n=C.findNode(db.quote.products,id);if(!n)return;openDialog('Chọn mã cho '+esc(n.name),`${select('Mã vật tư','material',db.materials.map(m=>[m.id,m.id+' / '+m.name+(m.brand?' / '+m.brand:'')]),'')}<p>Giữ định danh dòng, vị trí, số lượng và công đoạn. Quy cách/giá lấy từ mã chọn; bản gốc không đổi.</p>`,'Áp dụng mã',f=>{inWritable();const m=db.materials.find(m=>m.id===f.get('material'));if(!m)throw Error('Chọn mã');saveAndClose(()=>DFC().assign(n,m,db.rules));});}
function dfDimensions(id){const n=C.findNode(db.quote.products,id),d=n?.spec?.shapeDefinition;if(!d)return;const inputs=d.fields.filter(f=>f.mode==='input');openDialog('Thông số theo quy ước · '+esc(n.name),`${d.polygon?'<p class="notice">Nhập C1, C2… theo thứ tự đi quanh biên, không phải Dài / Rộng / Cao / Dày. '+(d.polygon.kind==='interior'?'A1 là góc trong giữa cạnh 1 và cạnh 2. Với hình chữ nhật hoặc bình hành, hai cặp cạnh đối bằng nhau.':'')+' Chiều dày T được khai riêng theo mã vật tư.</p>':''}<p>${esc(d.name)} · phiên bản ${d.version||1}. ${esc(d.condition||'')}</p><div class="form-grid">${inputs.map(f=>field(f.key+' — '+(f.name||TPConventions.parameterName(db,f.key))+' ('+f.unit+')',f.key,n.dims[f.key]??'','number','min="0" step="any" required')).join('')}</div><p>Cố định theo mã: ${d.fields.filter(f=>f.mode==='fixed').map(f=>esc(f.key)+' = '+num(n.spec.props[f.key])+' '+esc(f.unit)).join('; ')}.</p><output id="definition-dim-preview" class="notice"></output><p>Dài: <code>${esc(d.length)}</code>; rộng: <code>${esc(d.width)}</code>; kg trên đơn vị: <code>${esc(d.mass)}</code>; diện tích trên đơn vị: <code>${esc(d.surface)}</code>.</p>`,'Lưu thông số',f=>{inWritable();const dims={...n.dims,...Object.fromEntries(inputs.map(x=>[x.key,Number(f.get(x.key))]))};DFC().geometry({...n,dims},1);saveAndClose(()=>n.dims=dims);});const form=$('#dialog-form'),preview=()=>{try{const dims={...n.dims,...Object.fromEntries(inputs.map(x=>[x.key,Number(form.elements[x.key].value)]))},g=DFC().geometry({...n,dims},1),count=result.nodes[id].count;$('#definition-dim-preview').textContent=`Một chi tiết: ${num(g.weight,4)} kg · ${num(g.blankArea,4)} m². Toàn đơn: ${num(g.weight*count,4)} kg · ${num(g.blankArea*count,4)} m².`;}catch(e){$('#definition-dim-preview').textContent=e.message;}};form.addEventListener('input',preview);preview();}
function installDefinitionUI(){
 const shapesBefore=rcShapes;rcShapes=()=>`<div class="notice"><strong>Mẫu tham khảo tấm và thanh</strong><p>10 trường hợp có sẵn thông số, công thức và khổ mua để kiểm thử.</p>${dfButton("Mở các mẫu khai báo","examples")}</div>`+shapesBefore();
  const rules=renderRules;renderRules=()=>dfRules()+`<div class="actions">${dfButton('Khổ chuẩn theo máy/xưởng','stocks')}</div>`+rules();
  const materials=renderMaterials;renderMaterials=()=>`<div class="actions">${dfButton('Tạo vật tư theo quy ước','material-new')}${dfButton('Khổ chuẩn theo máy/xưởng','stocks')}</div>`+materials();
  const picker=batchMaterialPicker;batchMaterialPicker=(...args)=>{picker(...args);if($('#pick-search'))$('#pick-spec').insertAdjacentHTML('beforebegin',dfButton('Thêm dòng nháp — chọn mã sau','draft',args[0]));};
  const swap=actions['swap-material'];actions['swap-material']=el=>C.findNode(db.quote.products,el.dataset.id)?.draftMaterial||C.findNode(db.quote.products,el.dataset.id)?.spec?.shapeDefinition?dfAssign(el.dataset.id):swap(el);
  const details=renderMaterialDetail;renderMaterialDetail=n=>n.draftMaterial?`<section class="panel"><div class="panel-body"><h2>Vật tư nháp — chưa chọn mã</h2><p>Chưa đủ dữ liệu tính giá. Không dùng số 0 làm giá xác nhận.</p>${dfButton('Chọn mã vật tư','assign',n.id)}</div></section>`:n.spec.shapeDefinition?`<section class="panel"><div class="panel-body"><h2>${esc(n.spec.shapeDefinition.name)}</h2><p>Phiên bản ${n.spec.shapeDefinition.version||1} đã lưu cùng báo giá. ${esc(n.spec.shapeDefinition.condition||'')}</p><p>${esc(specText(n.spec))}</p>${dfButton('Nhập thông số & thử kết quả','dimensions',n.id)}${dfButton('Đổi mã vật tư','assign',n.id)}</div></section>`:details(n);
  const tools=mfgNodeActions;mfgNodeActions=n=>tools(n)+(n.spec?.shapeDefinition?dfButton('Thông số quy ước','dimensions',n.id):'');
  const refresh=render;render=()=>{refresh();for(const el of document.querySelectorAll('[data-b1-node]')){const n=C.findNode(db.quote.products,el.dataset.b1Node);if(n?.draftMaterial){el.classList.add('def-incomplete');const cost=el.querySelector('[data-qcost]');if(cost)cost.textContent='Chưa có giá';}if(el.classList.contains('quick-product-head')&&nodeProblem(n)){el.classList.add('b1-problem');el.querySelector('.quick-product-title')?.insertAdjacentHTML('beforeend',`<small class="def-problem">${esc(nodeProblem(n))}</small>`);}let status='';if(typeof Team!=='undefined'&&Team.loaded&&(!Team.permissions?.edit||Team.link?.status!=='draft'||Team.link?.readOnly)){el.classList.add('def-locked');status='Đã khóa';}else if(db.quote.status==='approved'){el.classList.add('def-approved');status='Đã duyệt';}if(status){el.setAttribute('aria-label',status+' · '+(n?.name||''));const target=el.querySelector('.quick-product-title,.quick-identity>span:last-child,.b1-identity>div,.node-copy,th');target?.insertAdjacentHTML('beforeend',`<small class="def-state">${status}</small>`);}}};
  document.addEventListener('click',e=>{const stock=e.target.closest('[data-batch-one="stock"]');if(stock){e.preventDefault();e.stopImmediatePropagation();try{dfChooseStock(stock.dataset.id);}catch(err){inError(err);}return;}const b=e.target.closest('[data-definition]');if(!b)return;const a=b.dataset.definition,id=b.dataset.id;if(['add-field','drop-field','add-output','drop-output'].includes(a))return;e.preventDefault();try{if(a==='examples')dfExamples();else if(a==='example')dfShapeEdit(undefined,{id:'QD-'+C.uid(),...DFC().example(id)});else if(a==='shape-new')dfShapeEdit();else if(a==='shape-edit')dfShapeEdit(id);else if(a==='shape-material')dfMaterial(id);else if(a==='material-new'){const defs=db.shapeDefinitions||[];if(!defs.length)return dfShapeEdit();openDialog('Chọn quy ước cho mã mới',select('Quy ước','definition',defs.map(d=>[d.id,d.name]),defs[0].id),'Tiếp tục',f=>dfMaterial(f.get('definition')));}else if(a==='stocks')dfStockList();else if(a==='stock-new')dfStockEdit();else if(a==='stock-edit')dfStockEdit(id);else if(a==='draft')dfDraft(id);else if(a==='assign')dfAssign(id);else if(a==='dimensions')dfDimensions(id);}catch(err){inError(err);}},true);
}
